import React, { useState } from "react";
import { useNavigate } from "react-router-dom";


const AdPage = () => {
  const navigate = useNavigate();

  const [cards, setCards] = useState([
    {
      title: "Smartphone Deals",
      desc: "Top smartphones at best prices!",
      img: "https://source.unsplash.com/300x200/?smartphone",
    },
    {
      title: "Laptop Offers",
      desc: "High performance laptops on sale!",
      img: "https://source.unsplash.com/300x200/?laptop",
    },
  ]);

  const topProducts = [
    {
      title: "Wireless Earbuds",
      img: "https://source.unsplash.com/200x200/?earbuds",
    },
    {
      title: "Smartwatch",
      img: "https://source.unsplash.com/200x200/?smartwatch",
    },
    {
      title: "Gaming Mouse",
      img: "https://source.unsplash.com/200x200/?mouse,gaming",
    },
  ];

  const topBrands = [
    {
      name: "Apple",
      img: "https://source.unsplash.com/200x200/?apple,logo",
    },
    {
      name: "Samsung",
      img: "https://source.unsplash.com/200x200/?samsung,logo",
    },
    {
      name: "Dell",
      img: "https://source.unsplash.com/200x200/?dell,logo",
    },
  ];

  return (
    <div className="adpage">
      <div className="ad-banner">
        <img
          src="https://source.unsplash.com/1200x300/?sale,ecommerce"
          alt="Ad Banner"
        />
      </div>

      <div className="card-list">
        {cards.map((card, i) => (
          <div
            className="product-card"
            key={i}
            onClick={() => navigate("/products")}
          >
            <img src={card.img} alt={card.title} />
            <h3>{card.title}</h3>
            <p>{card.desc}</p>
          </div>
        ))}
      </div>

      <h2 style={{ marginLeft: "20px" }}>Top Products</h2>
      <div className="top-section">
        {topProducts.map((product, index) => (
          <div
            className="top-card"
            key={index}
            onClick={() => navigate("/products")}
          >
            <img src={product.img} alt={product.title} />
            <p>{product.title}</p>
          </div>
        ))}
      </div>

      <h2 style={{ marginLeft: "20px" }}>Top Brands</h2>
      <div className="top-section">
        {topBrands.map((brand, index) => (
          <div
            className="top-card"
            key={index}
            onClick={() => navigate("/products")}
          >
            <img src={brand.img} alt={brand.name} />
            <p>{brand.name}</p>
          </div>
        ))}
      </div>
    </div>
  );
};

export default AdPage;
